"""Publish aggregate audit evidence and hand-reviewed assertions from cached records."""
from __future__ import annotations

import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
LOCAL = ROOT / "data/processed_combat_reality_1/final"
PUBLIC = ROOT / "reports/combat_reality_1"

# Reviewed against pre-action numbers/keywords/text, not generated by the extractor.
# damage to source, shield lost, source body dies, source HP after packet,
# damage to target, shield lost, target body dies, target HP after packet.
HAND_EXCHANGE = [
    [1, False, False, 1, 3, False, False, 1],
    [6, False, True, 0, 3, False, False, 3],
    [6, False, True, 0, 3, False, False, 3],
    [3, False, False, 2, 2, False, True, 0],
    [2, False, False, 3, 2, False, True, -1],
    [2, False, True, -1, 3, False, True, 0],
    [2, False, False, 3, 4, False, True, -2],
    [4, False, True, -2, 0, True, False, 4],
    [3, False, True, -2, 2, False, True, 1],
]
HAND_RELATIONS = [
    [False, -1, 1, 1], [False, -3, 0, 6], [False, -3, 0, 6],
    [True, 0, 2, 3], [True, 1, 3, 2], [True, 0, -1, 2],
    [True, 2, 3, 2], [False, -3, -2, 4], [False, -1, -2, 3],
]


def write(path, value):
    with path.open("x", encoding="utf-8", newline="\n") as f:
        json.dump(value, f, ensure_ascii=False, indent=2, sort_keys=True)
        f.write("\n")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--local", type=Path, default=LOCAL)
    parser.add_argument("--out", type=Path, default=PUBLIC)
    args = parser.parse_args()
    outputs = [args.out / name for name in ("coverage.json", "manual_audit.json", "matches.md")]
    if any(path.exists() for path in outputs): raise ValueError("Fresh report outputs required")
    summary = json.loads((args.local / "summary.json").read_text(encoding="utf-8"))
    sample = json.loads((args.local / "private_manual_sample.json").read_text(encoding="utf-8"))
    assert len(sample) == len(HAND_EXCHANGE) == 9
    relation_keys = ["attack_ge_health", "attack_health_margin", "health_retaliation_margin", "retaliation_attack"]
    exchange_keys = [side + "_" + suffix for side in ("source", "target")
                     for suffix in ("damage_packet", "shield_removed", "body_dies", "health_after_packet")]
    cases = []
    for number, (item, ordinary, relations) in enumerate(zip(sample, HAND_EXCHANGE, HAND_RELATIONS, strict=True), 1):
        p = item["record"]["result"]["properties"]
        assert [p[k]["value"] for k in exchange_keys] == ordinary
        assert [p[k]["value"] for k in relation_keys] == relations
        expected_level = "VERIFIED_LOCAL" if number == 6 else "CONDITIONAL"
        assert all(p[k]["knownness"] == expected_level for k in exchange_keys)
        assert all(p[k]["knownness"] == "OBSERVED" for k in relation_keys)
        cases.append({"case": number, "strata": item["strata"], "exchange_level": expected_level,
                      "hand_expected_exchange": dict(zip(exchange_keys, ordinary, strict=True)),
                      "hand_expected_relations": dict(zip(relation_keys, relations, strict=True)),
                      "refusal_reasons": item["record"]["result"]["blockers"], "passed": True})
    records = json.loads((args.local / "private_records.json").read_text(encoding="utf-8"))
    status = {}
    for r in records:
        if any(v["knownness"] == "VERIFIED_LOCAL" for v in r["result"]["properties"].values()):
            k = r["result"]["outcome_status"]
            status[k] = status.get(k, 0) + 1
    summary["verified_local_by_outcome_status"] = status
    # Every published object is an aggregate or an anonymous local-property audit.
    args.out.mkdir(parents=True, exist_ok=True)
    write(args.out / "coverage.json", summary)
    write(args.out / "manual_audit.json", {"selection": "first pre-action feature-stratified cases in pinned split order",
                                          "cases": cases, "value_assertions": 108, "level_assertions": 108,
                                          "limitations": "nine cases are not independent game-quality evaluation; Immune/unknown flags covered by isolated tests, absent in real attack sample"})
    lines = ["# Покрытие по матчам", "", "Номера локальные и анонимные. Доли рассчитаны по отдельным легальным атакам.", "",
             "| Матч | Класс SELF | Решения с атакой / все | Атаки | Существо → существо: наблюдаемые отношения / все атаки | Локально проверенный обмен / все атаки |",
             "|---|---|---:|---:|---:|---:|"]
    for r in summary["matches"]:
        n = r.get("attacks", 0)
        m, v = r.get("with_observed_relations", 0), r.get("with_verified_local_exchange", 0)
        ratio = lambda value: f"{value}/{n} ({100*value/n:.2f}%)" if n else "0/0 — атак нет"
        lines.append(f"| {r['match']} | {r['class']} | {r['decisions_with_attacks']}/{r['decisions']} | {n} | {ratio(m)} | {ratio(v)} |")
    with (args.out / "matches.md").open("x", encoding="utf-8", newline="\n") as f:
        f.write("\n".join(lines) + "\n")
    print("Published aggregates; 108 independent value assertions and 108 level assertions passed.")


if __name__ == "__main__":
    main()
